import sys

def main():
    data = sys.stdin.read().split('\\n')
    first = data[0].split()
    H, W, k = int(first[0]), int(first[1]), int(first[2])
    grid = [list(data[1 + i][:W]) for i in range(H)]
    for _ in range(k):
        new = [['.'] * W for _ in range(H)]
        for i in range(H):
            for j in range(W):
                cnt = 0
                for di in (-1, 0, 1):
                    for dj in (-1, 0, 1):
                        if di == 0 and dj == 0:
                            continue
                        ni, nj = i + di, j + dj
                        if 0 <= ni < H and 0 <= nj < W and grid[ni][nj] == '#':
                            cnt += 1
                if grid[i][j] == '#':
                    if cnt == 2 or cnt == 3:
                        new[i][j] = '#'
                else:
                    if cnt == 3:
                        new[i][j] = '#'
        grid = new
    sys.stdout.write('\\n'.join(''.join(row) for row in grid) + '\\n')

main()
